421fcb7 Record WI-002 split acceptance checks
function parseDecimal(value, name) {
  if (!/^\d+(?:\.\d+)?$/.test(value ?? '')) {
    throw new Error(`${name} must be a nonnegative decimal number`);
  }

  const [whole, fraction = ''] = value.split('.');
  return {
    coefficient: BigInt(whole + fraction),
    scale: fraction.length,
  };
}

function roundHalfUp(numerator, denominator) {
  return (2n * numerator + denominator) / (2n * denominator);
}

function dollars(cents) {
  return `$${cents / 100n}.${(cents % 100n).toString().padStart(2, '0')}`;
}

function parseSplit(value) {
  if (!/^\d+$/.test(value ?? '') || BigInt(value) === 0n) {
    throw new Error('Split count must be a positive whole number');
  }
  return BigInt(value);
}

try {
  const args = process.argv.slice(2);
  if ((args.length !== 3 && args.length !== 5) || args[1] !== '--percent'
      || (args.length === 5 && args[3] !== '--split')) {
    throw new Error('Usage: node bin/tipcalc.js <bill> --percent <percentage> [--split <count>]');
  }

  const bill = parseDecimal(args[0], 'Bill');
  const percent = parseDecimal(args[2], 'Percentage');
  const split = args.length === 5 ? parseSplit(args[4]) : null;
  const billDenominator = 10n ** BigInt(bill.scale);
  const tipDenominator = 10n ** BigInt(bill.scale + percent.scale);
  const tipCents = roundHalfUp(bill.coefficient * percent.coefficient, tipDenominator);
  const billCents = roundHalfUp(bill.coefficient * 100n, billDenominator);
  const totalCents = billCents + tipCents;

  process.stdout.write(`Tip: ${dollars(tipCents)}  Total: ${dollars(totalCents)}\n`);
  if (split !== null) {
    const shareCents = (totalCents + split - 1n) / split;
    process.stdout.write(`Each person pays: ${dollars(shareCents)}\n`);
  }
} catch (error) {
  process.stderr.write(`Error: ${error.message}\n`);
  process.exitCode = 1;
}
